import{_ as a,o as s,c as n,a2 as d}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"案例 03 · 快餐薯条社媒短视频","description":"","frontmatter":{},"headers":[],"relativePath":"cases/case-03-fries-social.md","filePath":"cases/case-03-fries-social.md","lastUpdated":1786327499000}'),r={name:"cases/case-03-fries-social.md"};function e(p,t,o,l,i,h){return s(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="案例-03-·-快餐薯条社媒短视频" tabindex="-1">案例 03 · 快餐薯条社媒短视频 <a class="header-anchor" href="#案例-03-·-快餐薯条社媒短视频" aria-label="Permalink to &quot;案例 03 · 快餐薯条社媒短视频&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">这是教学演示案例</p><p>用于展示食品类内容的「食欲感」怎么做，以及首尾帧控制的用法。<strong>不是真实客户项目的复盘</strong>，数字为基于典型情况的合理估计。</p></div><blockquote><p><strong>一句话</strong>：食品广告的成败在食欲感，而 AI 的默认输出会把食物拍成塑料模型。</p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>品类</td><td>连锁快餐 · 薯条单品</td></tr><tr><td>交付形态</td><td>8 秒竖屏</td></tr><tr><td>投放渠道</td><td>抖音 / 小红书</td></tr><tr><td>工期</td><td>1.5 天</td></tr><tr><td>出片率</td><td>约 60 条生成 / 5 条采用</td></tr></tbody></table><hr><h2 id="_1-创意点" tabindex="-1">① 创意点 <a class="header-anchor" href="#_1-创意点" aria-label="Permalink to &quot;① 创意点&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>连锁快餐的薯条单品推广，目标人群 18–25 岁的学生与年轻白领，投放在深夜时段的社媒信息流。</p><p>限制：不能虚构口感描述、不能用「最」这类绝对化用语（见 <a href="/prompts/copywriting">文案合规</a>）。</p><h3 id="一个反常识的判断-这支片子不需要-big-idea" tabindex="-1">一个反常识的判断：这支片子不需要 Big Idea <a class="header-anchor" href="#一个反常识的判断-这支片子不需要-big-idea" aria-label="Permalink to &quot;一个反常识的判断：这支片子不需要 Big Idea&quot;">​</a></h3><p>前两个案例都从洞察推到 Big Idea。这一支<strong>故意不这么做</strong>。</p><p>单品种草类内容，观众要的不是创意，是<strong>馋</strong>。一个巧妙的概念会分走注意力——他在想&quot;这个创意有意思&quot;，而不是&quot;我想吃&quot;。</p><div class="tip custom-block"><p class="custom-block-title">值得单独记住的一条</p><p><strong>不是所有广告都需要 Big Idea。</strong></p><p>需要的：品类竞争激烈、产品同质化、要建立品牌记忆的。 不需要的：单品种草、限时促销、产品本身有强感官吸引力的。</p><p>后一类里，把感官刺激做足，比想一个聪明的概念有效得多。判断错了会很尴尬——给薯条配一个深刻的概念，观众只会觉得用力过猛。</p></div><h3 id="策略" tabindex="-1">策略 <a class="header-anchor" href="#策略" aria-label="Permalink to &quot;策略&quot;">​</a></h3><blockquote><p><strong>全片只讲一件事：热，和脆。</strong></p></blockquote><p>八秒钟，不讲故事、不出现人脸、不放 slogan（放在最后一屏字幕上），所有镜头都服务于这两个字。</p><h3 id="淘汰掉的方向与理由" tabindex="-1">淘汰掉的方向与理由 <a class="header-anchor" href="#淘汰掉的方向与理由" aria-label="Permalink to &quot;淘汰掉的方向与理由&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>淘汰理由</th></tr></thead><tbody><tr><td>朋友聚会分享薯条的温馨场景</td><td>需要人物表演——AI 的弱项；且「快乐分享」和「馋」无关，走偏了</td></tr><tr><td>讲土豆产地和原料故事</td><td>8 秒的种草视频里没人关心故事，这是品牌片的做法</td></tr><tr><td>薯条拟人化的动画角色</td><td>可爱，但可爱不等于馋。方向性错误</td></tr></tbody></table><p><strong>共同问题</strong>：三个方向都在往&quot;创意&quot;上使劲，而这支片子需要的是往&quot;感官&quot;上使劲。</p><hr><h2 id="_2-生成链路" tabindex="-1">② 生成链路 <a class="header-anchor" href="#_2-生成链路" aria-label="Permalink to &quot;② 生成链路&quot;">​</a></h2><h3 id="先定「食欲感四要素」" tabindex="-1">先定「食欲感四要素」 <a class="header-anchor" href="#先定「食欲感四要素」" aria-label="Permalink to &quot;先定「食欲感四要素」&quot;">​</a></h3><p>食品广告有一套成熟的经验，和 AI 无关，但决定了 Prompt 该怎么写：</p><table tabindex="0"><thead><tr><th>要素</th><th>为什么有效</th><th>在 Prompt 里怎么落</th></tr></thead><tbody><tr><td><strong>热气</strong></td><td>热=刚做好=新鲜，最直接的食欲信号</td><td>蒸汽 + <strong>逆光</strong>（见下）</td></tr><tr><td><strong>质感对比</strong></td><td>外脆内软的反差，靠&quot;断面&quot;呈现</td><td>掰断镜头，露出内部</td></tr><tr><td><strong>油脂光泽</strong></td><td>高光暗示油润，但过了就假</td><td>「轻微油光」而非「反光」</td></tr><tr><td><strong>动作</strong></td><td>拿起、掰断、蘸取——动作让人代入</td><td>首尾帧控制</td></tr></tbody></table><p>**这四条就是分镜表的来源。**先有食品广告的常识，再有分镜，最后才是 Prompt。</p><h3 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 定食欲感四要素清单（人，靠品类常识）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>② 图像模型生成关键帧，重点死磕质感 ← 时间主要花在这</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>③ 首尾帧控制生成动作镜头 ← 本案例的新技术点</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>④ 升格处理热气与掉落</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑤ 音效设计（食品类的特殊环节，见下）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>⑥ 剪辑，快节奏</span></span></code></pre></div><h3 id="分镜表" tabindex="-1">分镜表 <a class="header-anchor" href="#分镜表" aria-label="Permalink to &quot;分镜表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>时长</th><th>景别</th><th>主体与动作</th><th>光</th><th>运镜</th></tr></thead><tbody><tr><td>1</td><td>0–2s</td><td>特写</td><td>一篮薯条被放到桌面，热气升腾</td><td>强侧逆光，蒸汽被点亮</td><td>固定</td></tr><tr><td>2</td><td>2–3.5s</td><td>微距</td><td>手指捏起一根，表面有轻微油光</td><td>侧逆光</td><td>缓慢上移</td></tr><tr><td>3</td><td>3.5–5.5s</td><td>微距</td><td><strong>掰断</strong>，露出内部粉质断面，一缕热气冒出</td><td>逆光</td><td>固定，升格</td></tr><tr><td>4</td><td>5.5–7s</td><td>特写</td><td>蘸入番茄酱后缓慢拉起，酱料垂落</td><td>侧光</td><td>固定，升格</td></tr><tr><td>5</td><td>7–8s</td><td>特写</td><td>薯条移向画面外（不进嘴），字幕出</td><td>侧逆光</td><td>固定</td></tr></tbody></table><p>**镜头 3 是全片的核心。**外脆内软的对比只能靠断面呈现，这是食品摄影的老技巧（业内叫「断裂镜头」），在 AI 上同样成立。</p><p>**镜头 5 故意不拍咬下去。**原因见下面的可复用套路第 5 条。</p><h3 id="数字" tabindex="-1">数字 <a class="header-anchor" href="#数字" aria-label="Permalink to &quot;数字&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>总生成 / 采用</td><td>约 60 条 / 5 条</td></tr><tr><td>质感调试（关键帧）</td><td>约 半天</td></tr><tr><td>视频生成</td><td>约 半天</td></tr><tr><td>音效 + 剪辑</td><td>约 半天</td></tr><tr><td>返工点</td><td><strong>镜头 3（掰断）废片率最高</strong>，约占总生成量的四成</td></tr></tbody></table><p><strong>关于镜头 3</strong>：掰断是一个&quot;物体发生不可逆形变&quot;的过程，视频模型对此处理很差——常见的翻车是薯条断了又&quot;愈合&quot;、断面凭空长出不存在的结构、或者两截的长度加起来远超原长。这类镜头必须用<strong>首尾帧控制</strong>，且要留足重试次数。</p><hr><h2 id="_3-关键-prompt" tabindex="-1">③ 关键 Prompt <a class="header-anchor" href="#_3-关键-prompt" aria-label="Permalink to &quot;③ 关键 Prompt&quot;">​</a></h2><h3 id="prompt-1-·-食欲感风格包-解决塑料感" tabindex="-1">Prompt 1 · 食欲感风格包（解决塑料感） <a class="header-anchor" href="#prompt-1-·-食欲感风格包-解决塑料感" aria-label="Permalink to &quot;Prompt 1 · 食欲感风格包（解决塑料感）&quot;">​</a></h3><p><strong>适用场景</strong> 所有镜头共用。食品类项目的通用底子。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>食品广告微距摄影，暖色调，轻微胶片颗粒，</span></span>
<span class="line"><span>100mm 微距镜头，极浅景深 f/2.8，</span></span>
<span class="line"><span>强侧逆光从右后方打来，热气与蒸汽被逆光点亮呈半透明的白色，背景压暗虚化，</span></span>
<span class="line"><span>食物表面有轻微油光但不是塑料反光，</span></span>
<span class="line"><span>表面有不均匀的金黄至浅褐色斑点，边缘形状不规则，</span></span>
<span class="line"><span>竖版 9:16，高细节，真实食物质感</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：文字、水印、塑料感、蜡质感、完美均匀的表面、过度光滑、CGI 感</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>在控制什么</th><th>想改效果时</th></tr></thead><tbody><tr><td><strong>不均匀的斑点 + 边缘不规则</strong></td><td>**本条最关键。**真实食物是不完美的，AI 默认输出太整齐所以显假</td><td>想更真实就加&quot;局部有轻微焦褐&quot;</td></tr><tr><td>轻微油光但不是塑料反光</td><td>油润感和塑料感只隔一线，这句在划界</td><td>出图发亮得不自然就把&quot;轻微&quot;改成&quot;极轻微&quot;</td></tr><tr><td>热气被逆光点亮</td><td>**蒸汽只在逆光下可见。**写了蒸汽却用顺光，等于没写</td><td>想让热气更明显，加&quot;背景为深色&quot;</td></tr><tr><td>塑料感 / 蜡质感 / CGI 感（负向）</td><td>食品类必备的三个排除项</td><td>——</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>食物太完美</strong>。这是食品类 AI 图最典型的破绽：每根薯条一样长、颜色均匀、表面光滑——像塑料模型。<strong>主动往 Prompt 里加&quot;不完美&quot;的描述</strong>，这是反直觉但必须做的一步。</li><li><strong>热气写了但看不见</strong>。蒸汽是半透明的，只有在深色背景 + 逆光的组合下才显形。光位不对，热气就消失了。</li><li><strong>油光过头</strong>。写&quot;反光&quot;&quot;光泽&quot;容易得到镜面效果，一看就假。「轻微油光」是安全表述。</li></ul><hr><h3 id="prompt-2-·-镜头-3-掰断-首尾帧控制" tabindex="-1">Prompt 2 · 镜头 3 掰断（首尾帧控制） <a class="header-anchor" href="#prompt-2-·-镜头-3-掰断-首尾帧控制" aria-label="Permalink to &quot;Prompt 2 · 镜头 3 掰断（首尾帧控制）&quot;">​</a></h3><p><strong>适用场景</strong> 有明确起止状态的形变动作。这是本案例新引入的技术点。</p><p><strong>做法</strong></p><p>先用图像模型生成两张图：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【首帧】</span></span>
<span class="line"><span>一根完整的炸薯条被两只手指捏住，悬在深色桌面上方，</span></span>
<span class="line"><span>[粘贴风格包]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【尾帧】</span></span>
<span class="line"><span>一根被掰成两截的炸薯条，两截仍被手指捏住并略微分开，</span></span>
<span class="line"><span>断面朝向镜头，露出内部浅黄色的粉质结构，一缕白色热气从断面升起，</span></span>
<span class="line"><span>[粘贴风格包]</span></span></code></pre></div><p>再把两张图作为起止帧输入视频模型：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[首帧图] → [尾帧图]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>薯条被缓慢掰断，断面朝向镜头，热气从断口升起，</span></span>
<span class="line"><span>其余部分保持静止</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：快速运动、镜头切换、变形、薯条数量变化、手指变形</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>要点</th><th>作用</th></tr></thead><tbody><tr><td>首尾帧都要生成到满意</td><td>**尾帧的断面质量决定这个镜头的成败。**先把尾帧调好，再回头做首帧</td></tr><tr><td>薯条数量变化（负向）</td><td>掰断过程中模型爱&quot;变出&quot;第三截</td></tr><tr><td>手指变形（负向）</td><td>有手就必查，参见 <a href="/prompts/product-still#通用检查清单">产品静物的通用检查清单</a></td></tr><tr><td>其余部分保持静止</td><td>不写的话背景会飘</td></tr></tbody></table><p><strong>常见翻车点</strong></p><ul><li><strong>断面「愈合」</strong>。断开后又合上，或者中途反复。这是形变类动作的典型失败，只能靠多生成筛选。</li><li><strong>两截加起来比原来长</strong>。模型不守恒。首尾帧控制能大幅缓解，但仍要逐条检查。</li><li><strong>用文生视频做这个镜头</strong>。基本不可能成功——形变过程需要明确的起止约束。<strong>这类镜头就是首尾帧控制存在的意义。</strong></li></ul><hr><h3 id="prompt-3-·-镜头-4-酱料垂落-升格" tabindex="-1">Prompt 3 · 镜头 4 酱料垂落（升格） <a class="header-anchor" href="#prompt-3-·-镜头-4-酱料垂落-升格" aria-label="Permalink to &quot;Prompt 3 · 镜头 4 酱料垂落（升格）&quot;">​</a></h3><p><strong>适用场景</strong> 液体、酱料的缓慢流动。食品类的高频镜头。</p><p><strong>可复制 Prompt</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[输入首帧图：薯条刚从番茄酱中提起]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>薯条被极缓慢地向上提起，一滴番茄酱从薯条末端缓慢垂落拉出细丝，</span></span>
<span class="line"><span>其余部分保持静止</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向：快速运动、镜头切换、酱料飞溅、多滴酱料、变形</span></span></code></pre></div><p><strong>参数说明</strong></p><table tabindex="0"><thead><tr><th>关键词</th><th>作用</th></tr></thead><tbody><tr><td><strong>一滴</strong></td><td>数量写死。写&quot;酱料垂落&quot;会得到一团乱流</td></tr><tr><td>拉出细丝</td><td>粘稠感的关键。液体的&quot;拉丝&quot;是食欲信号</td></tr><tr><td>极缓慢</td><td>升格效果，同时避开模型的快速运动弱项</td></tr><tr><td>酱料飞溅（负向）</td><td>不排除的话经常出现莫名的飞溅</td></tr></tbody></table><p><strong>常见翻车点</strong></p><p>粘稠液体的物理行为是视频模型的难点之一——酱料会违反重力横向流动、或者凭空增量。<strong>排期给这类镜头留双倍时间</strong>（和 <a href="/cases/case-01-beverage-tvc">案例 01</a> 里的气泡镜头是同一类问题）。</p><hr><h2 id="_4-可复用套路" tabindex="-1">④ 可复用套路 <a class="header-anchor" href="#_4-可复用套路" aria-label="Permalink to &quot;④ 可复用套路&quot;">​</a></h2><ol><li><p>**食物的真实感来自不完美。**主动在 Prompt 里写「不均匀的斑点」「边缘不规则」「局部焦褐」。这条反直觉——多数人写 Prompt 时在追求完美，但完美的食物看起来就是塑料。<strong>这是食品类 AI 图最重要的一条。</strong></p></li><li><p>**热气只在逆光下可见。**蒸汽是半透明的，顺光下拍不出来。要热气就必须配「强侧逆光 + 深色背景」。写了蒸汽却看不见，九成是光位的问题，不是描述的问题。</p></li><li><p>**有明确起止状态的形变动作，用首尾帧控制。**掰断、倒出、展开、融化——这类镜头文生视频做不了，图生视频也不稳，首尾帧是唯一可靠的路。先把尾帧调满意再做首帧。</p></li><li><p>**食品类视频里，音效比配乐重要。**油炸的滋滋声、掰断的脆响、酱料的黏腻声——这类 ASMR 式的音效对食欲的刺激强于任何 BGM。<strong>留出专门的时间做音效</strong>，别在剪辑时随手套个背景音乐了事。这一条在别的品类里不成立，食品类里是决定性的。</p></li><li><p>**避开入口和咀嚼的镜头。**嘴部、牙齿、舌头是 AI 的重灾区，一旦画错极其违和，而且这类镜头没法靠后期补救。<strong>改成&quot;食物移向画面外&quot;然后切走</strong>——观众会自行脑补，效果一样，风险为零。这属于&quot;绕过去比硬碰划算&quot;的典型。</p></li><li><p>**不是所有广告都需要 Big Idea。**单品种草、限时促销、感官驱动的品类，把感官做足比想概念有效。<strong>判断这一点应该在动手之前</strong>——方向错了，后面所有努力都在错误的路上加速。</p></li></ol><h2 id="如果重做一次" tabindex="-1">如果重做一次 <a class="header-anchor" href="#如果重做一次" aria-label="Permalink to &quot;如果重做一次&quot;">​</a></h2><p><strong>镜头 1 和镜头 2 应该合并。</strong></p><p>8 秒的片子里，前两个镜头（端上桌 + 捏起一根）都是铺垫，占掉了 3.5 秒——将近一半。而真正让人馋的是镜头 3（断面热气）和镜头 4（酱料拉丝）。</p><p>合并成一个 1.5 秒的开场，把省下的 2 秒分给镜头 3 和 4，食欲感的密度会高很多。</p><p>**教训：短视频里，铺垫是最先该砍的。**这和 <a href="/cases/case-01-beverage-tvc#如果重做一次">案例 01</a> 得出的结论一致——两个项目都在开头浪费了时间。看来这是我的一个固定倾向，下次做分镜时提前警惕。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li><strong>同为薯条、但卖工艺不卖感官</strong> → <a href="/cases/case-04-vf-fries-crisp">案例 04 · VF 工艺薯条脆</a>（建议紧接着读，两篇是一组对照）</li><li>为什么这套食欲感拍法不能直接套到袋装薯条脆上 → <a href="/cases/case-04-fries-crisp-formats">片型可行性分析</a></li><li>视频链路的基本走法 → <a href="/cases/case-01-beverage-tvc">案例 01 · 饮料品牌短 TVC</a></li><li>静态图批量生产 → <a href="/cases/case-02-ecommerce-visual">案例 02 · 电商主图批量生产</a></li><li>分镜方法 → <a href="/method/storyboard">分镜设计</a></li></ul>`,75)])])}const u=a(r,[["render",e]]);export{g as __pageData,u as default};
